73:         // Check if the chainlink price is broken or frozen.
74:         if (chainlinkPrice == 0) return 0;
75: 
76:         uint256 stethPerWsteth = IWsteth(C.WSTETH).stEthPerToken();
77: 
78:         chainlinkPrice = chainlinkPrice.mul(stethPerWsteth).div(CHAINLINK_DENOMINATOR);
79: 
80:         // Uniswap V3 only supports a uint32 lookback.
81:         if (lookback > type(uint32).max) return 0;
82:         uint256 uniswapPrice = LibUniswapOracle.getTwap(
83:             lookback == 0 ? LibUniswapOracle.FIFTEEN_MINUTES : uint32(lookback),
84:             C.WSTETH_ETH_UNIV3_01_POOL,
85:             C.WSTETH,
86:             C.WETH,
87:             ONE
88:         );
89: 
90:         // Check if the uniswapPrice oracle fails.
91:         if (uniswapPrice == 0) return 0;
92: 
93:         if (LibOracleHelpers.getPercentDifference(chainlinkPrice, uniswapPrice) < MAX_DIFFERENCE) {
94:             wstethEthPrice = chainlinkPrice.add(uniswapPrice).div(AVERAGE_DENOMINATOR);
95:             if (wstethEthPrice > stethPerWsteth) wstethEthPrice = stethPerWsteth;
96:             wstethEthPrice = wstethEthPrice.div(PRECISION_DENOMINATOR);
